interface LevelUpProps {
  /** Level before the level-up. The new level is `level + 1`. */
  level?: number;
  /** XP already in the bar when the shot opens. */
  startXp?: number;
  /** XP needed for the next level. The chips should add up to `maxXp - startXp`. */
  maxXp?: number;
  /** One chip per entry, each flies into the bar. */
  chips?: number[];
  /** Big erupting call. */
  title?: string;
  /** Stat line that ticks up on the poster. */
  stat?: { label: string; value: number; suffix?: string };
  /** Caption under the bar. */
  barLabel?: string;
  /** Shown under the bar once it is full. */
  maxLabel?: string;
  /** Unit after the XP counter and on the chips. */
  unit?: string;
  /** Small accent: the stat arrow and the level label marker. */
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the copy. Load it yourself; Chakra Petch by default. */
  fontFamily?: string;
  /** Replaces the remocn mark under the stat line. */
  logo?: React.ReactNode;
  /** Size of the foreground, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
  /**
   * Moves, trims or stretches the bar, single chips, the max-out, the
   * collapse, the burst, the duck, the roll and the stat line, by the ids in
   * `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<LevelUpElementId>;
}

// Beat sheet (30fps, speed 1):
//   0–10   the segmented XP bar builds left to right, labels slide in
//   6–48   XP chips fly into the fill head one after another, speeding up;
//          each hit fills the bar a step, flashes the new segment and ticks the
//          counter
//  48–51   the bar maxes out and flashes
//  51–58   the bar collapses into the centre point
//  58–66   "LEVEL UP" erupts from that point with a burst of gradient rays and
//          one shockwave ring
//  68–76   the call ducks to a kicker, the old level number rises in big
//  82–90   the changed digit rolls 41 → 42 and lands with a kick
//  94–106  the stat line slides in and ticks up; poster hold to the end
const SEGMENTS = 10;

const OUT = Easing.bezier(0.22, 1, 0.36, 1);
const SLAM = Easing.bezier(0.12, 0.9, 0.25, 1);
const INOUT = Easing.bezier(0.65, 0, 0.25, 1);
const IN = Easing.bezier(0.5, 0, 0.9, 0.6);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "beam": bg #02030a, [#f4f7ff, #8fb4ff, #3d5bff, #1a1660].
const BEAM = ["#F4F7FF", "#8FB4FF", "#3D5BFF", "#1A1660"] as const;

const THEMES = {
  dark: {
    stage: "#050609",
    ink: "#F3F2EF",
    dim: "#8A8A93",
    track: "#16171E",
    chip: "#0E1020",
    chipEdge: BEAM[1],
    rayAlpha: 1,
    rays: [BEAM[0], BEAM[1], BEAM[2], BEAM[3]],
    fill: `linear-gradient(90deg, ${BEAM[3]} 0%, ${BEAM[2]} 38%, ${BEAM[1]} 78%, ${BEAM[0]} 100%)`,
    number: `linear-gradient(180deg, ${BEAM[0]} 8%, ${BEAM[1]} 52%, ${BEAM[2]} 96%)`,
  },
  light: {
    stage: "#F5F4F0",
    ink: "#121214",
    dim: "#7E7D77",
    track: "#E3E1DA",
    chip: "#FFFFFF",
    chipEdge: BEAM[2],
    rayAlpha: 0.7,
    rays: [BEAM[2], BEAM[2], BEAM[1], BEAM[1]],
    fill: `linear-gradient(90deg, ${BEAM[3]} 0%, ${BEAM[2]} 45%, ${BEAM[1]} 100%)`,
    number: `linear-gradient(180deg, ${BEAM[2]} 8%, #2A2FB8 55%, ${BEAM[3]} 96%)`,
  },
} as const;

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

function hash(n: number) {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
}

function fmt(n: number) {
  return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

/** A short hit: up in 2 frames, eases back over 8. */
function kick(d: number) {
  if (d < 0) return 0;
  if (d < 2) return d / 2;
  const k = Math.max(0, 1 - (d - 2) / 8);
  return k * k;
}

// Chip launch points, relative to the bar centre in units of W and H.
const LAUNCH = [
  { x: -0.36, y: -0.36 },
  { x: 0.3, y: -0.4 },
  { x: -0.22, y: 0.36 },
  { x: 0.06, y: -0.42 },
  { x: 0.34, y: 0.34 },
];

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function LevelUpBase(props: LevelUpProps) {
  const {
    level = 41,
    startXp = 2800,
    maxXp = 4000,
    chips = DEFAULT_CHIPS,
    title = "LEVEL UP",
    stat = { label: "Render speed", value: 40, suffix: "%" },
    barLabel = "EXPERIENCE",
    maxLabel = "MAX",
    unit = "XP",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = hud,
    logo,
    scale = 1,
    delay = 0,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    levelUpTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const barEl = tl.get("bar");
  const chipEls = chips.map((_, i) => tl.get(`chip:${i}`));
  const maxEl = tl.get("max");
  const collapseEl = tl.get("collapse");
  const burstEl = tl.get("burst");
  const BURST_AT = burstEl.start;
  const duckEl = tl.get("duck");
  const rollEl = tl.get("roll");
  const statEl = tl.get("stat");
  const STAT_AT = statEl.start;
  const c = THEMES[theme];
  const fg = ink ?? c.ink;
  // The burst fades into the stage colour, so a custom fill takes its place.
  const knock =
    background === undefined || background === "transparent"
      ? c.stage
      : background;
  const u = Math.min(W / 1280, H / 720);
  const id = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  const cx = W / 2;
  const cy = 0.53 * H;

  // ── XP state ──────────────────────────────────────────────────────────────
  // A chip hits the bar at the end of its flight.
  const arrivals = chipEls.map((e) => e.end);
  let xp = startXp;
  chips.forEach((v, i) => {
    xp += v * OUT(ramp(t, arrivals[i], chipEls[i].beat("fill")));
  });
  const fill = Math.min(1, xp / maxXp);
  const lastHit = arrivals.reduce((acc, a) => (t >= a ? a : acc), -99);
  const hitKick = kick(t - lastHit);

  // ── Bar geometry ──────────────────────────────────────────────────────────
  const barW = 0.66 * W;
  const barH = 34 * u;
  const gap = 7 * u;
  const segW = (barW - gap * (SEGMENTS - 1)) / SEGMENTS;
  const collapse = INOUT(ramp(t, collapseEl.start, collapseEl.length));
  const maxFlash =
    t >= maxEl.start
      ? Math.max(0, 1 - (t - maxEl.start) / maxEl.beat("flash"))
      : 0;
  const barGone = t >= collapseEl.end;
  const labelsIn = OUT(
    ramp(t, barEl.start + barEl.beat("labelsAt"), barEl.beat("labels")),
  );
  const labelsOut = ramp(t, collapseEl.start, collapseEl.beat("labels"));

  // ── Burst ─────────────────────────────────────────────────────────────────
  const burst = OUT(ramp(t, BURST_AT, burstEl.length));
  const burstOp = ramp(t, BURST_AT, burstEl.beat("raysFade"));
  const rollHit = rollEl.end;
  const rayPulse = kick(t - rollHit + 1);
  const spin = Math.max(0, t - BURST_AT) * 0.22;
  const ring = ramp(t, BURST_AT, burstEl.length);

  const titleFs = 140 * u;
  const titleIn = SLAM(ramp(t, BURST_AT, burstEl.beat("title")));
  const duck = INOUT(ramp(t, duckEl.start, duckEl.length));
  const titleScale =
    interpolate(titleIn, [0, 1], [1.7, 1]) *
    interpolate(duck, [0, 1], [1, 0.36]);
  // The duck to the top is a transform on the title, not `top`: layout
  // rounds a baseline to whole pixels, so a title eased by `top` clicks up
  // pixel by pixel. Laid out where it parks.
  const titleRise = (cy - 0.2 * H) * (1 - duck);
  const titleMoving = midway(titleIn) || midway(duck);

  // ── Big level number ──────────────────────────────────────────────────────
  const numFs = 360 * u;
  const numAt = duckEl.start + duckEl.beat("numAt");
  const numIn = OUT(ramp(t, numAt, duckEl.beat("num")));
  const roll = SLAM(ramp(t, rollEl.start, rollEl.length));
  const from = String(level);
  const to = String(level + 1);
  const len = Math.max(from.length, to.length);
  const fromP = from.padStart(len, " ");
  const toP = to.padStart(len, " ");
  const numKick = 1 + 0.045 * kick(t - rollHit);
  const numMoving =
    midway(numIn) || (t > rollHit && t < rollHit + rollEl.beat("kick"));

  // ── Stat line ─────────────────────────────────────────────────────────────
  const statP = OUT(ramp(t, STAT_AT, statEl.length));
  const statAt = (f: number) =>
    Math.round(
      stat.value *
        OUT(ramp(f, STAT_AT + statEl.beat("countAt"), statEl.beat("count"))),
    );
  const statN = statAt(t);
  // The count reflows the centred line sideways in layout; the lean stays on
  // until the number has stopped, so it never goes in a frame that reflows.
  const statMoving =
    midway(statP) || statAt(t + speed) !== statN || statAt(t - speed) !== statN;
  const logoP = OUT(
    ramp(t, STAT_AT + statEl.beat("logoAt"), statEl.beat("logo")),
  );

  // Rays: wedges from an inner radius out, alternating widths and lengths.
  const RAYS = 24;
  const r0 = interpolate(burst, [0, 1], [0.05, 0.3]) * H;
  const reach = interpolate(burst, [0, 1], [0.3, 1]) * (1 + 0.06 * rayPulse);
  const rays = Array.from({ length: RAYS }, (_, i) => {
    const a = ((i / RAYS) * 360 + spin) * (Math.PI / 180);
    const half = (i % 2 === 0 ? 2.2 : 0.9) * (Math.PI / 180);
    const R = (0.42 + 0.38 * hash(i)) * W * reach;
    const ri = r0;
    const p = (ang: number, r: number) =>
      `${cx + Math.cos(ang) * r},${cy + Math.sin(ang) * r}`;
    return `M${p(a - half * 0.4, ri)} L${p(a - half, R)} L${p(a + half, R)} L${p(a + half * 0.4, ri)} Z`;
  });

  const chipFs = 30 * u;

  return (
    <AbsoluteFill
      style={{
        background:
          background === "transparent" ? undefined : (background ?? c.stage),
        overflow: "hidden",
      }}
    >
      <ScaleLayer scale={scale}>
        {/* Burst rays and the shockwave ring. */}
        {t >= BURST_AT ? (
          <svg
            width={W}
            height={H}
            style={{
              position: "absolute",
              inset: 0,
              opacity:
                burstOp *
                c.rayAlpha *
                (0.5 +
                  0.5 *
                    (1 -
                      ramp(
                        t,
                        BURST_AT + burstEl.beat("raysAt"),
                        burstEl.beat("rays"),
                      )) +
                  0.3 * rayPulse),
            }}
            aria-hidden
          >
            <defs>
              <radialGradient
                id={`${id}-ray`}
                cx={cx}
                cy={cy}
                r={0.8 * W}
                gradientUnits="userSpaceOnUse"
              >
                <stop offset="0.12" stopColor={c.rays[0]} stopOpacity={0.95} />
                <stop offset="0.3" stopColor={c.rays[1]} stopOpacity={0.75} />
                <stop offset="0.6" stopColor={c.rays[2]} stopOpacity={0.45} />
                <stop offset="1" stopColor={c.rays[3]} stopOpacity={0} />
              </radialGradient>
            </defs>
            {rays.map((d, i) => (
              <path key={i} d={d} fill={`url(#${id}-ray)`} />
            ))}
            {ring < 1 ? (
              <circle
                cx={cx}
                cy={cy}
                r={interpolate(OUT(ring), [0, 1], [0.04 * W, 0.5 * W])}
                fill="none"
                stroke={BEAM[1]}
                strokeWidth={interpolate(ring, [0, 1], [5 * u, 0.5 * u])}
                opacity={1 - ring}
              />
            ) : null}
          </svg>
        ) : null}

        {t >= BURST_AT ? (
          <div
            style={{
              position: "absolute",
              inset: 0,
              opacity: ramp(
                t,
                BURST_AT + burstEl.beat("glowAt"),
                burstEl.beat("glow"),
              ),
              background: [
                `radial-gradient(30% 34% at 50% ${(cy / H) * 100}%, ${knock} 45%, transparent 100%)`,
                `linear-gradient(0deg, ${knock} 0%, ${knock} 12%, transparent 34%)`,
              ].join(", "),
            }}
          />
        ) : null}

        {/* XP bar. */}
        {!barGone ? (
          <div
            style={{
              position: "absolute",
              left: cx - barW / 2,
              top: cy - barH / 2,
              width: barW,
              height: barH,
              transform: `scaleX(${1 - collapse}) scaleY(${1 - 0.6 * collapse})`,
              transformOrigin: "50% 50%",
            }}
          >
            {Array.from({ length: SEGMENTS }, (_, i) => {
              const x = i * (segW + gap);
              const appear = OUT(
                ramp(
                  t,
                  barEl.start + i * barEl.beat("segment"),
                  barEl.beat("appear"),
                ),
              );
              const f = Math.max(0, Math.min(1, fill * SEGMENTS - i));
              const justFilled =
                f > 0 && fill * SEGMENTS - i < 1.6 && hitKick > 0 ? hitKick : 0;
              return (
                <div
                  key={i}
                  style={{
                    position: "absolute",
                    left: x,
                    top: 0,
                    width: segW,
                    height: barH,
                    background: c.track,
                    transform: `skewX(-20deg) scaleY(${0.3 + 0.7 * appear})`,
                    opacity: appear,
                    overflow: "hidden",
                  }}
                >
                  <div
                    style={{
                      position: "absolute",
                      left: 0,
                      top: 0,
                      bottom: 0,
                      width: `${f * 100}%`,
                      backgroundImage: c.fill,
                      backgroundSize: `${barW}px ${barH}px`,
                      backgroundPosition: `${-x}px 0`,
                    }}
                  />
                  <div
                    style={{
                      position: "absolute",
                      left: 0,
                      top: 0,
                      bottom: 0,
                      width: `${f * 100}%`,
                      background: BEAM[0],
                      opacity: Math.max(0.85 * justFilled, maxFlash),
                    }}
                  />
                </div>
              );
            })}
          </div>
        ) : null}

        {/* Labels above the bar. */}
        {labelsOut < 1 ? (
          <div
            style={{
              position: "absolute",
              left: cx - barW / 2,
              width: barW,
              top: cy - barH / 2 - 128 * u,
              height: 110 * u,
              display: "flex",
              alignItems: "flex-end",
              justifyContent: "space-between",
              opacity: labelsIn * (1 - labelsOut),
              transform: `translateY(${(1 - labelsIn) * 16 * u}px)${glide(midway(labelsIn))}`,
              fontFamily,
              fontWeight: 500,
              color: fg,
            }}
          >
            <div
              style={{ display: "flex", alignItems: "baseline", gap: 14 * u }}
            >
              <span
                style={{
                  fontSize: 30 * u,
                  letterSpacing: "0.14em",
                  color: c.dim,
                }}
              >
                LV
              </span>
              <span
                style={{
                  fontSize: 112 * u,
                  lineHeight: 0.8,
                  letterSpacing: "-0.02em",
                }}
              >
                {level}
              </span>
            </div>
            <div
              style={{
                fontSize: 32 * u,
                letterSpacing: "0.04em",
                fontVariantNumeric: "tabular-nums",
                marginBottom: 2 * u,
              }}
            >
              {fmt(xp)}
              <span style={{ color: c.dim }}>
                {" "}
                / {fmt(maxXp)} {unit}
              </span>
            </div>
          </div>
        ) : null}
        {labelsOut < 1 ? (
          <div
            style={{
              position: "absolute",
              left: cx - barW / 2,
              width: barW,
              top: cy + barH / 2 + 18 * u,
              display: "flex",
              justifyContent: "space-between",
              opacity: labelsIn * (1 - labelsOut),
              fontFamily,
              fontWeight: 400,
              fontSize: 20 * u,
              letterSpacing: "0.16em",
              color: c.dim,
            }}
          >
            <span>{barLabel}</span>
            <span style={{ color: fill >= 1 ? fg : c.dim }}>
              {fill >= 1 ? maxLabel : `NEXT  LV ${level + 1}`}
            </span>
          </div>
        ) : null}

        {/* XP chips flying into the fill head. */}
        {chips.map((v, i) => {
          const chip = chipEls[i];
          const launch = chip.start;
          if (t < launch || t >= launch + chip.beat("gone")) return null;
          const p = ramp(t, launch, chip.length);
          const e = IN(p);
          const L = LAUNCH[i % LAUNCH.length];
          const sx = cx + L.x * W;
          const sy = cy + L.y * H;
          const headX = cx - barW / 2 + barW * Math.min(1, (xp + 0) / maxXp);
          const tx = headX;
          const ty = cy;
          const mx = (sx + tx) / 2 + (L.y < 0 ? -1 : 1) * 0.06 * W;
          const my = (sy + ty) / 2 + (L.y < 0 ? -0.12 : 0.12) * H;
          const x = (1 - e) * (1 - e) * sx + 2 * (1 - e) * e * mx + e * e * tx;
          const y = (1 - e) * (1 - e) * sy + 2 * (1 - e) * e * my + e * e * ty;
          const appear = OUT(ramp(t, launch, chip.beat("appear")));
          const k = interpolate(e, [0, 1], [1, 0.5]) * (0.85 + 0.15 * appear);
          const op =
            appear *
            (1 - ramp(t, launch + chip.beat("fadeAt"), chip.beat("fade")));
          return (
            <div
              key={`${i}-${v}`}
              style={{
                // Layout rounds a box and a baseline to whole pixels, so a
                // chip flown by `left`/`top` lands on whole pixels and its
                // steps come out uneven. It is laid out at the bar's centre
                // and the flight is a transform; a chip is never at rest.
                position: "absolute",
                left: cx,
                top: cy,
                transform: `translate(${x - cx}px, ${y - cy}px) translate(-50%, -50%) scale(${k})${glide(true)}`,
                opacity: op,
                padding: `${9 * u}px ${18 * u}px ${8 * u}px`,
                borderRadius: 999,
                background: c.chip,
                border: `${1.5 * u}px solid ${c.chipEdge}`,
                fontFamily,
                fontWeight: 500,
                fontSize: chipFs,
                lineHeight: 1,
                letterSpacing: "0.02em",
                color: fg,
                whiteSpace: "nowrap",
              }}
            >
              +{v} <span style={{ color: c.chipEdge }}>{unit}</span>
            </div>
          );
        })}

        {/* LEVEL UP call. */}
        {t >= BURST_AT ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              width: W,
              top: 0.2 * H - titleFs * 0.6,
              height: titleFs * 1.2,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transform: `translateY(${titleRise}px) scale(${titleScale})${glide(titleMoving)}`,
              opacity: ramp(t, BURST_AT, burstEl.beat("fade")),
              fontFamily,
              fontWeight: 500,
              fontSize: titleFs,
              lineHeight: 1,
              letterSpacing: "0.04em",
              color: ink ?? (theme === "dark" ? "#FFFFFF" : c.ink),
              whiteSpace: "nowrap",
            }}
          >
            {title}
          </div>
        ) : null}

        {/* Big level number: the changed digits roll. */}
        {t >= numAt ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              width: W,
              top: cy - numFs * 0.5,
              height: numFs,
              display: "flex",
              justifyContent: "center",
              opacity: numIn,
              transform: `translateY(${(1 - numIn) * 50 * u}px) scale(${numKick})${glide(numMoving)}`,
              fontFamily,
              fontWeight: 500,
              fontSize: numFs,
              lineHeight: 1,
              letterSpacing: "-0.03em",
            }}
          >
            {Array.from({ length: len }, (_, i) => {
              const a = fromP[i];
              const b = toP[i];
              const same = a === b;
              const glyph = (ch: string) => (
                <div
                  style={{
                    height: numFs,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    backgroundImage: c.number,
                    WebkitBackgroundClip: "text",
                    backgroundClip: "text",
                    color: "transparent",
                  }}
                >
                  {ch.trim() === "" ? " " : ch}
                </div>
              );
              return (
                <div
                  key={i}
                  style={{
                    width: "0.6em",
                    height: numFs,
                    overflow: "hidden",
                    position: "relative",
                  }}
                >
                  <div
                    style={{
                      transform: same
                        ? undefined
                        : `translateY(${-roll * numFs}px)${glide(midway(roll))}`,
                    }}
                  >
                    {glyph(a)}
                    {same ? null : glyph(b)}
                  </div>
                </div>
              );
            })}
          </div>
        ) : null}

        {/* Stat line. */}
        {t >= STAT_AT ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              width: W,
              top: 0.8 * H,
              display: "flex",
              justifyContent: "center",
              alignItems: "baseline",
              gap: 18 * u,
              opacity: statP,
              transform: `translateY(${(1 - statP) * 22 * u}px)${glide(statMoving)}`,
              fontFamily,
              fontWeight: 500,
              fontSize: 34 * u,
              lineHeight: 1,
              letterSpacing: "0.02em",
              color: fg,
            }}
          >
            <span style={{ color: c.dim }}>{stat.label}</span>
            <span
              style={{
                display: "flex",
                alignItems: "baseline",
                gap: 8 * u,
                fontVariantNumeric: "tabular-nums",
              }}
            >
              <svg
                width={18 * u}
                height={15 * u}
                viewBox="0 0 18 15"
                aria-hidden
                style={{ alignSelf: "center" }}
              >
                <path d="M9 0 L18 15 L0 15 Z" fill={accent} />
              </svg>
              +{statN}
              {stat.suffix ?? ""}
            </span>
          </div>
        ) : null}

        {/* Logo. */}
        <div
          style={{
            position: "absolute",
            left: 0,
            width: W,
            top: 0.9 * H,
            display: "flex",
            justifyContent: "center",
            opacity: logoP,
          }}
        >
          {logo ?? <RemocnLogo fontSize={26 * u} color={fg} />}
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  title: {
    type: "text-content",
    default: "LEVEL UP",
    description: "Title",
  },
  barLabel: {
    type: "text-content",
    default: "EXPERIENCE",
    description: "Bar label",
  },
  maxLabel: {
    type: "text-content",
    default: "MAX",
    description: "Max label",
  },
  unit: {
    type: "text-content",
    default: "XP",
    description: "Unit",
  },
  level: {
    type: "number",
    default: 41,
    min: 0,
    max: 123,
    step: 1,
    description: "Level",
    hiddenFromList: false,
  },
  startXp: {
    type: "number",
    default: 2800,
    min: 0,
    max: 8400,
    step: 1,
    description: "Start xp",
    hiddenFromList: false,
  },
  maxXp: {
    type: "number",
    default: 4000,
    min: 0,
    max: 12000,
    step: 1,
    description: "Max xp",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Chakra Petch",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
