    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","title","barLabel","maxLabel","unit","level","startXp","maxXp","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  title: "LEVEL UP",
  barLabel: "EXPERIENCE",
  maxLabel: "MAX",
  unit: "XP",
  level: 41,
  startXp: 2800,
  maxXp: 4000,
  accent: "#3B5BFD",
  fontFamily: "Chakra Petch",
  scale: 1,
  delay: 0,
  speed: 1,
};

type LevelUpElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof LevelUpBase>;

const LevelUpInner = forwardRef<
  HTMLDivElement,
  LevelUpElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<LevelUp>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <LevelUpBase
          {...(componentProps as unknown as ComponentProps<typeof LevelUpBase>)}
        />
      </div>
    </Sequence>
  );
});

export const LevelUp = Interactive.withSchema({
  Component: LevelUpInner,
  componentName: "<LevelUp>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
